#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (matches floyd-warshall.c's "floyd-warshall.h")
#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize the path matrix using the same logic as the original C code:
//
//   for (i = 0; i < n; i++)
//     for (j = 0; j < n; j++) {
//       path[i][j] = i*j%7+1;
//       if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
//          path[i][j] = 999;
//     }
//
// C layout: path[i][j]  =>  Halide layout: path(j, i)
static void init_array(int n, Halide::Buffer<num_t, 2> path) {
    Var i("i"), j("j");
    Func init_path("init_path");

    // Compute base value: i*j % 7 + 1
    Expr base = (i * j) % 7 + 1;

    // Predicate for setting large value 999
    Expr s = i + j;
    Expr cond = (s % 13 == 0) || (s % 7 == 0) || (s % 11 == 0);

    // Note: Buffer is indexed as (x = j, y = i)
    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             cast<num_t>(base));

    // Realize into the provided buffer
    init_path.realize(path);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Allocate path matrix (width = columns = n, height = rows = n)
    Halide::Buffer<num_t, 2> path(n, n);
    Halide::Buffer<num_t, 2> temp(n, n);  // temporary for double buffering

    // Initialize data
    init_array(n, path);

    // Declare Halide pipeline for a single Floyd–Warshall relaxation step.
    //
    // Original kernel:
    //
    // for (k = 0; k < n; k++)
    //   for (i = 0; i < n; i++)
    //     for (j = 0; j < n; j++)
    //       path[i][j] = min(path[i][j], path[i][k] + path[k][j]);
    //
    // We express a *single* step for fixed k as a pure Func:
    //   step(i,j) = min(P(i,j), P(i,k) + P(k,j))
    // and then iterate over k on the host, using double buffering.

    ImageParam P(type_of<num_t>(), 2, "P");  // current path matrix
    Param<int> k_param("k");                 // current k in outer loop

    Var i("i"), j("j");
    Func step("step");

    // Mapping C indices path[i][j] -> P(j, i):
    //   path[i][j] -> P(j, i)
    //   path[i][k] -> P(k, i)
    //   path[k][j] -> P(j, k)
    step(j, i) = min(P(j, i),
                     P(k_param, i) + P(j, k_param));

    // Default schedule: outer loop over i, inner over j,
    // matching the C order for i and j.
    // No explicit schedule needed, but could be:
    // step.reorder(j, i);

    // Bind initial buffer and compile once (outside timing)
    P.set(path);
    step.compile_jit();

    // Measure the time of the Floyd–Warshall kernel only
    auto start = std::chrono::high_resolution_clock::now();

    // Host-driven outer loop over k, with double buffering between path and temp.
    for (int k = 0; k < n; k++) {
        k_param.set(k);

        // Compute next state into temp
        step.realize(temp);

        // Swap buffers: new state becomes 'path'
        std::swap(path, temp);
        P.set(path);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump results, similar to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Remember: path[i][j] in C is path(j, i) in Halide
                std::cerr << path(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}

