#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// Include benchmark-specific definitions (N, DATA_TYPE, etc.).
#include "floyd-warshall.h"

using namespace Halide;

// Match PolyBench's DATA_TYPE with a C++ alias
using num_t = DATA_TYPE;

/**
 * Initialize the path matrix.
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       path[i][j] = i*j%7+1;
 *       if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
 *          path[i][j] = 999;
 *     }
 *
 * Note: C uses path[i][j] with row-major layout (i = row, j = col).
 * In Halide::Buffer, the first dimension is the fastest-varying (x, i.e., column),
 * and the second is the slower (y, i.e., row). So we map path[i][j] -> path(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> path) {
    Var i("i"), j("j");
    Func init_path("init_path");

    Expr base = cast<num_t>((i * j) % 7 + 1);
    Expr sum_ij = i + j;
    Expr cond = ((sum_ij % 13) == 0) ||
                ((sum_ij % 7) == 0) ||
                ((sum_ij % 11) == 0);

    init_path(j, i) = select(cond, cast<num_t>(999), base);

    // Realize into the provided Buffer. path has shape (n, n).
    init_path.realize(path);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Allocate path matrix as a Halide buffer.
    // As per the mapping, path(i,j in C) == path(j,i in Halide).
    Halide::Buffer<num_t, 2> path(n, n);

    // Initialize data.
    init_array(n, path);

    // Halide representation of one Floyd–Warshall "step" for a fixed k.
    //
    // Original C kernel:
    //
    // for (k = 0; k < n; k++) {
    //   for (i = 0; i < n; i++)
    //     for (j = 0; j < n; j++)
    //       path[i][j] = path[i][j] < path[i][k] + path[k][j]
    //                    ? path[i][j] : path[i][k] + path[k][j];
    // }
    //
    // We express a single k-step as a Halide Func that reads from an ImageParam
    // representing the "current" path matrix, and we iterate over k on the host,
    // double-buffering between two Buffers. This avoids illegal self-referential
    // updates in Halide while preserving the algorithm's semantics.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");
    Func fw_step("fw_step");

    // Map path[i][j] -> path_param(j, i)
    //     path[i][k] -> path_param(k, i)
    //     path[k][j] -> path_param(j, k)
    Expr direct   = path_param(j, i);
    Expr via_k    = path_param(k_param, i) + path_param(j, k_param);
    fw_step(j, i) = min(direct, via_k);

    // Bind the ImageParam once to give Halide shape information.
    path_param.set(path);

    // JIT-compile the step function once; we'll call it multiple times.
    fw_step.compile_jit();

    // Double buffers for iterative updates over k.
    Halide::Buffer<num_t, 2> curr = path;        // current path matrix
    Halide::Buffer<num_t, 2> next(n, n);         // next path matrix

    // Measure only the Floyd–Warshall computation time (not JIT time).
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; k++) {
        k_param.set(k);
        path_param.set(curr);

        // Compute next(i,j) = FW_step(curr, k)[i,j]
        fw_step.realize(next);

        // Swap current and next (cheap: Buffers are ref-counted handles).
        Halide::Buffer<num_t, 2> tmp = curr;
        curr = next;
        next = tmp;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // 'curr' now holds the final path matrix. For convenience, alias it as 'path'.
    path = curr;

    // Optionally print the result matrix, similar in spirit to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_row = 0; i_row < n; i_row++) {
            for (int j_col = 0; j_col < n; j_col++) {
                std::cerr << path(j_col, i_row) << '\n';
            }
        }
    }

    // Print elapsed time in seconds, with microsecond resolution.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
