#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the path matrix.
 *
 * C version:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       path[i][j] = i*j%7+1;
 *       if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
 *          path[i][j] = 999;
 *     }
 *
 * Our Buffer layout is path(j, i) == path[i][j].
 */
static
void init_array(int n, Halide::Buffer<num_t, 2> path) {
    Var i("i"), j("j");
    Func init_path("init_path");

    // i = row index, j = column index
    Expr base = i * j % 7 + 1;

    Expr sum = i + j;
    Expr cond =
        (sum % 13 == 0) ||
        (sum % 7  == 0) ||
        (sum % 11 == 0);

    // First argument is the column (j), second is the row (i)
    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             cast<num_t>(base));

    // Realize into the provided buffer (shape: n x n)
    init_path.realize(path);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Allocate Buffers.
    // As in the GEMM example, we store matrix element [i][j] at (j, i),
    // so first dimension is the column index, second is the row index.
    Halide::Buffer<num_t, 2> path(n, n);      // current state
    Halide::Buffer<num_t, 2> path_tmp(n, n);  // next state (for double buffering)

    // Initialize data (equivalent to init_array in the C version)
    init_array(n, path);

    // Halide representation of the Floyd–Warshall single-iteration step:
    //
    // For a given k, we want:
    //   path_new[i][j] = min(path_old[i][j],
    //                        path_old[i][k] + path_old[k][j]);
    //
    // We implement this as:
    //   fw_step(j, i) = min(path_param(j, i),
    //                       path_param(k_param, i) + path_param(j, k_param));
    //
    // Note: We use double buffering (Jacobi-style) across k to avoid
    // illegal self-referential updates in Halide. For the positive
    // weights used in this benchmark, this produces the same final
    // result as the in-place C implementation.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");
    Func fw_step("fw_step");

    fw_step(j, i) = Halide::min(
        path_param(j, i),
        path_param(k_param, i) + path_param(j, k_param));

    // Bind initial buffer and compile once (JIT).
    path_param.set(path);
    k_param.set(0);
    fw_step.compile_jit();

    // Start timer: only the kernel (the n^3 loop) is timed,
    // matching the PolyBench behavior.
    auto start = std::chrono::high_resolution_clock::now();

    // Main Floyd–Warshall k-loop, driven from the host.
    for (int k = 0; k < n; k++) {
        k_param.set(k);        // current pivot k
        path_param.set(path);  // read from current state

        // Compute next state into path_tmp.
        fw_step.realize(path_tmp);

        // Swap buffers so that 'path' always holds the latest result.
        std::swap(path, path_tmp);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional printing of the result matrix, similar to PolyBench's
    // print_array to prevent dead-code elimination.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_row = 0; i_row < n; i_row++) {
            for (int j_col = 0; j_col < n; j_col++) {
                // Recall: path(j, i) corresponds to path[i][j]
                std::cerr << path(j_col, i_row) << '\n';
            }
        }
    }

    // Print execution time in seconds (similar format to the GEMM example)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
