// include common definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, etc.)
#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization, translated to Halide. */
static
void init_array(int n, Halide::Buffer<num_t, 2> path) {
    // C code:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++) {
    //     path[i][j] = i*j%7+1;
    //     if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
    //        path[i][j] = 999;
    //   }

    Var i("i"), j("j");
    Func init_path("init_path");

    // Base value: i*j % 7 + 1
    Expr base = (i * j) % 7 + 1;
    Expr base_val = cast<num_t>(base);

    Expr sum = i + j;
    Expr mark_inf =
        ((sum % 13) == 0) ||
        ((sum % 7)  == 0) ||
        ((sum % 11) == 0);

    // Map C path[i][j] to Halide path(j, i) (x = j, y = i)
    init_path(j, i) = select(mark_inf, cast<num_t>(999), base_val);

    init_path.realize(path);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers for the path matrix.
    // Following the mapping rule: C path[i][j] -> Halide path(j, i)
    Halide::Buffer<num_t, 2> path_cur(n, n);
    Halide::Buffer<num_t, 2> path_next(n, n);

    // Initialize data
    init_array(n, path_cur);

    // Halide representation of a single Floyd–Warshall step for a fixed k:
    //
    // path_new[i][j] = min(path_old[i][j], path_old[i][k] + path_old[k][j]).
    //
    // We implement this as a Func that reads from an ImageParam (current
    // path matrix) and a scalar Param k. The outer loop over k will be
    // done on the host, with double-buffering between iterations.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");
    Func floyd_step("floyd_step");

    // Map indices carefully:
    // C: path[i][j]       -> path_param(j, i)
    // C: path[i][k]       -> path_param(k_param, i)
    // C: path[k][j]       -> path_param(j, k_param)
    Expr current   = path_param(j, i);
    Expr via_k     = path_param(k_param, i) + path_param(j, k_param);
    floyd_step(j, i) = min(current, via_k);

    // Default schedule is fine; it will produce a loop nest equivalent to:
    // for (i) for (j) ...
    // because y (i) is outer and x (j) is inner.

    // Bind the initial buffer.
    path_param.set(path_cur);

    // JIT-compile the step kernel once.
    floyd_step.compile_jit();

    // Measure only the Floyd–Warshall iterations, not initialization or JIT.
    auto start = std::chrono::high_resolution_clock::now();

    // Main computational kernel: loop over k on the host side.
    for (int k = 0; k < n; ++k) {
        k_param.set(k);

        // Compute one Floyd–Warshall step from path_cur into path_next.
        floyd_step.realize(path_next);

        // Swap buffers: path_cur always holds the most recent result.
        std::swap(path_cur, path_next);
        path_param.set(path_cur);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix (similar to the example).
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Recall: path_cur(j, i) corresponds to C path[i][j]
                std::cerr << path_cur(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
